import os
import subprocess

# Try some likely URLs
candidates = ['startups.html', 'founders.html', 'airbnb.html', 'airbnbs.html']

for candidate in candidates:
    try:
        result = subprocess.run(['curl', '-s', f'https://paulgraham.com/{candidate}'], capture_output=True, text=True, timeout=5)
        if 'do things' in result.stdout.lower() or 'scale' in result.stdout.lower():
            if '<title>' in result.stdout:
                title = result.stdout.split('<title>')[1].split('</title>')[0]
                print(f"Found in {candidate}: {title}")
    except:
        pass
